import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Instalasi & Aktivasi","description":"","frontmatter":{"title":"Instalasi & Aktivasi"},"headers":[],"relativePath":"byok/instalasi.md","filePath":"byok/instalasi.md"}`),a={name:`byok/instalasi.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="instalasi-aktivasi-byok" tabindex="-1">Instalasi &amp; Aktivasi BYOK <a class="header-anchor" href="#instalasi-aktivasi-byok" aria-label="Permalink to “Instalasi &amp; Aktivasi BYOK”">​</a></h1><p>Halaman ini memandu kamu mengaktifkan mode <strong>BYOK (Bring Your Own Key)</strong> di Mikazuki AI — dari menyiapkan API key sampai percakapan pertama berjalan lewat key-mu sendiri.</p><h2 id="persyaratan" tabindex="-1">Persyaratan <a class="header-anchor" href="#persyaratan" aria-label="Permalink to “Persyaratan”">​</a></h2><p>Sebelum memulai, pastikan kamu sudah punya:</p><ul><li><strong>API key</strong> dari provider pilihanmu (mis. Google Gemini, Anthropic Claude, DeepSeek, OpenRouter — lihat daftar lengkap di <a href="./">Pengenalan BYOK</a>). <ul><li>Untuk provider berbasis endpoint publik (ArliAI, Mancer, AI Horde, NovelAI), API key tidak diperlukan.</li><li>Untuk <strong>OpenAI Compatible</strong>, kamu tidak selalu butuh key resmi — cukup <em>Base URL</em> dari server/endpoint kustommu.</li></ul></li><li>Akses ke aplikasi Mikazuki AI di perangkatmu.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Belum punya API key?</p><p>Provider seperti OpenRouter dan Groq menyediakan key gratis/kredit awal — cek dashboard provider masing-masing untuk membuat key pertamamu.</p></div><h2 id="langkah-aktivasi" tabindex="-1">Langkah Aktivasi <a class="header-anchor" href="#langkah-aktivasi" aria-label="Permalink to “Langkah Aktivasi”">​</a></h2><ol><li>Buka menu <strong>Pengaturan → Engine</strong> (<code>/settings/engine</code>).</li><li>Ubah <strong>Mode</strong> dari <code>System</code> menjadi <code>BYOK</code>.</li><li>Pilih <strong>Provider</strong>, tempel <strong>API Key</strong>, dan cari/pilih <strong>Model</strong> lewat tombol 🔍 (<em>Fetch Models</em>).</li><li>(Opsional) Bagi provider <code>OpenAI Compatible</code>/<code>Chutes</code>, isi <strong>Base URL</strong>.</li><li>Selesai — seluruh chat berikutnya akan lewat key-mu.</li></ol><h2 id="catatan-privasi-keamanan" tabindex="-1">Catatan Privasi &amp; Keamanan <a class="header-anchor" href="#catatan-privasi-keamanan" aria-label="Permalink to “Catatan Privasi &amp; Keamanan”">​</a></h2><blockquote><p>⚠️ <strong>Catatan Privasi:</strong> API key-mu <strong>disimpan lokal di perangkatmu</strong> (IndexedDB + localStorage), bukan di database server. Ia hanya melewati server sebagai bagian payload request saat mengobrol. Jangan bagikan key-mu ke siapa pun.</p></blockquote><p>Beberapa poin singkat:</p><ul><li>Key <strong>tidak pernah ditulis ke log server</strong> dan tidak disimpan di database.</li><li>Key hanya dikirim saat request percakapan berlangsung.</li><li>Jika key ter-publish tidak sengaja, segera <em>revoke</em> (cabut) key itu dari dashboard provider dan buat yang baru.</li></ul><h2 id="tips-openai-compatible-untuk-server-lokal" tabindex="-1">Tips: OpenAI Compatible untuk Server Lokal <a class="header-anchor" href="#tips-openai-compatible-untuk-server-lokal" aria-label="Permalink to “Tips: OpenAI Compatible untuk Server Lokal”">​</a></h2><p>Memakai Ollama atau llama.cpp di mesin sendiri? Pilih provider <strong>OpenAI Compatible</strong>, lalu isi <strong>Base URL</strong> dengan endpoint lokal yang memakai layout API OpenAI, misalnya <code>http://localhost:11434</code> untuk Ollama. Setelah itu tekan tombol 🔍 (<em>Fetch Models</em>) untuk memuat daftar model dari server lokal-mu.</p><div class="tip custom-block"><p class="custom-block-title">💡 Model tidak tampil di daftar?</p><p>Periksa API key dan <em>Base URL</em>, lalu tekan tombol 🔍 lagi. Jika provider menolak endpoint resmi atau memakai endpoint khusus, isi nama model secara manual pada kolom Model. Lihat juga bagian <a href="./#faq-singkat">FAQ singkat</a> di halaman Pengenalan BYOK.</p></div><h2 id="selanjutnya" tabindex="-1">Selanjutnya <a class="header-anchor" href="#selanjutnya" aria-label="Permalink to “Selanjutnya”">​</a></h2><ul><li>Kenali isi panel <strong>&quot;Opsi Lanjutan&quot;</strong> di halaman <a href="./parameter-dasar.html">Parameter Dasar</a>.</li><li>Kembali ke <a href="./">Pengenalan BYOK</a> untuk melihat daftar provider dan fitur yang tetap berjalan.</li></ul>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};